import time
import json

orcid_ids = [
    "0000-0003-0396-0333",  # Manuela Nagel
    "0000-0002-2605-6569",  # Tatjana Gavrilenko
    "0000-0001-6102-7846",  # John Bamberg
    "0000-0002-0209-2784",  # David Ellis
    "0000-0002-1053-2030",  # Peter Giovannini
]

names = {
    "0000-0003-0396-0333": "Manuela Nagel",
    "0000-0002-2605-6569": "Tatjana Gavrilenko",
    "0000-0001-6102-7846": "John Bamberg",
    "0000-0002-0209-2784": "David Ellis",
    "0000-0002-1053-2030": "Peter Giovannini",
}

results = {}

for orcid in orcid_ids:
    url = f"https://pub.orcid.org/v3.0/{orcid}/works"
    headers = {"Accept": "application/json"}
    print(f"Fetching works for {names[orcid]} ({orcid})...")
    try:
        response = requests.get(url, headers=headers, timeout=30)
        print(f"  Status: {response.status_code}")
        if response.status_code == 200:
            data = response.json()
            works = data.get("work-group", {}).get("work", [])
            print(f"  Total works: {len(works)}")

            pre_2020_count = 0
            for work in works:
                work_summary = work.get("work-summary", [])
                for summary in work_summary:
                    pub_date = summary.get("publication-date", {})
                    if pub_date:
                        year = pub_date.get("year", {}).get("value")
                        if year and int(year) < 2020:
                            pre_2020_count += 1
            print(f"  Pre-2020 works: {pre_2020_count}")
            results[orcid] = pre_2020_count
        else:
            print(f"  Response: {response.text[:500]}")
            results[orcid] = None
    except Exception as e:
        print(f"  Error: {e}")
        results[orcid] = None

    time.sleep(0.5)  # Rate limiting

print("\n--- Summary ---")
total_pre_2020 = 0
count = 0
for orcid, pre_2020 in results.items():
    if pre_2020 is not None:
        print(f"{names[orcid]}: {pre_2020} pre-2020 works")
        total_pre_2020 += pre_2020
        count += 1
    else:
        print(f"{names[orcid]}: Could not fetch")

if count > 0:
    average = total_pre_2020 / count
    print(f"\nTotal pre-2020 works: {total_pre_2020}")
    print(f"Number of researchers: {count}")
    print(f"Average: {average}")
else:
    print("No data available")"}

